css:
.hero__title-row {
  position: fixed;
  top: calc(50% - 56px + clamp(50px, 4.5vw, 90px));
  left: 4%;
  z-index: 2;
  display: flex;
  align-items: baseline;
  gap: clamp(112px, 12vw, 224px);
  color: #ffffff;
  font-weight: 200;
  pointer-events: none;
  transform: translate3d(15vw, var(--scroll-y, 0px), 0);
  will-change: transform, opacity;
}
